import{_ as e,o as l,c as a,a2 as o}from"./chunks/framework.CZGNF-7T.js";const f=JSON.parse('{"title":"수수료 정산 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/settlement.md","filePath":"sales/settlement.md","lastUpdated":1789130265000}'),r={name:"sales/settlement.md"};function d(n,t,s,i,g,c){return l(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="수수료-정산-관리" tabindex="-1">수수료 정산 관리 <a class="header-anchor" href="#수수료-정산-관리" aria-label="Permalink to &quot;수수료 정산 관리&quot;">​</a></h1><p>프로젝트의 정산 회차(월별/주기별)를 생성하고 대상 기간 동안 체결된 계약 실적과 수수료 정책을 매칭하여 개인별 수수료, 미정산 환수금 상계, 3.3% 원천세를 자동 계산 및 확정하는 페이지입니다.</p><ul><li><strong>위치</strong>: <code>PJT 관리 시스템 &gt; 분양 대행 관리 &gt; 수수료 정산 관리</code></li></ul><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>분양 대행사 및 영업 상담사에게 지급할 수수료를 주기별(예: 매월 말일 또는 격주 단위)로 집계하고 확정하는 정산 엔진을 제공합니다. 기간 내 체결된 계약과 계약별 지정 정책에 따라 기본 인센티브를 계산하고, 계약 해약 등으로 발생한 환수금(<code>CommissionClawback</code>)을 자동으로 상계 차감하며, 사업소득세 3% 및 지방소득세 0.3%(총 3.3%)를 법정 원단위 절사 방식으로 자동 계산하여 실지급액을 정확하게 도출합니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>정산 회차 생성</strong>: 정산 대상 기간(시작일~종료일), 지급 예정일, 회차명을 설정하여 회차 관리</li><li><strong>수수료 자동 정산 실행 (<code>generate-payouts</code>)</strong>: <ul><li>기간 내 체결된 유효 계약 실적 자동 집계</li><li>상담사, 팀장, 본부장 직책별 차등 수수료(R값) 산출</li><li>기존 미정산 환수금 자동 상계 처리</li><li>사업소득세 3% + 지방소득세 0.3% 원천징수세액 자동 차감</li></ul></li><li><strong>정산 확정 처리 (<code>confirm-settlement</code>)</strong>: 집계된 정산 명세를 최종 확정하여 지급 단계로 이관</li><li><strong>개인별 상세 정산 내역 조회</strong>: 팝업 모달을 통해 상담사별 계약 건별 수수료 산출 내역 및 계좌 정보 열람</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><h3 id="_1-회차-선택-및-제어-바" tabindex="-1">1. 회차 선택 및 제어 바 <a class="header-anchor" href="#_1-회차-선택-및-제어-바" aria-label="Permalink to &quot;1. 회차 선택 및 제어 바&quot;">​</a></h3><ul><li><strong>정산 회차 선택</strong>: 조회 및 정산 작업을 진행할 회차를 드롭다운으로 선택</li><li><strong>회차 상태 뱃지</strong>: 현재 회차의 진행 상태 표시 (<code>정산 작성 중</code>, <code>정산 확정</code>, <code>지급 완료</code>)</li><li><strong>[신규 회차 생성] 버튼</strong>: 새로운 정산 주기 회차를 생성하는 모달 호출 (<code>primary</code>)</li><li><strong>[수수료 자동 정산 실행] 버튼</strong>: 대상 기간 실적을 기반으로 정산 엔진을 일괄 가동 (<code>info</code>)</li><li><strong>[정산 확정] 버튼</strong>: 작성이 완료된 정산 내역을 승인 및 확정 상태로 변경 (<code>success</code>)</li></ul><h3 id="_2-정산-총괄-요약-카드" tabindex="-1">2. 정산 총괄 요약 카드 <a class="header-anchor" href="#_2-정산-총괄-요약-카드" aria-label="Permalink to &quot;2. 정산 총괄 요약 카드&quot;">​</a></h3><p>선택된 회차의 전체 정산 재무 집계 지표를 실시간 카드로 제공합니다.</p><ul><li><strong>정산 계약 건수</strong>: 해당 회차에 포함되어 정산된 총 계약 건수</li><li><strong>총 지급액 (세전)</strong>: 인센티브 합계 + 기본급/일비 - 환수 공제액</li><li><strong>원천징수 세액 (3.3%)</strong>: 사업소득세 3% + 지방소득세 0.3% 합계</li><li><strong>총 실지급액 (세후)</strong>: 세전 총액에서 원천징수세액을 차감한 실제 지급 대상 총액</li></ul><h3 id="_3-개인별-정산-및-세금-공제-명세-테이블" tabindex="-1">3. 개인별 정산 및 세금 공제 명세 테이블 <a class="header-anchor" href="#_3-개인별-정산-및-세금-공제-명세-테이블" aria-label="Permalink to &quot;3. 개인별 정산 및 세금 공제 명세 테이블&quot;">​</a></h3><p>회차 내 정산 대상 영업 인력별 상세 산출 내역을 표시합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>소속 팀 / 직책 / 성명</strong></td><td style="text-align:left;">영업 인력의 기본 인적 정보 (성명 클릭 시 상세 모달 팝업)</td></tr><tr><td style="text-align:left;"><strong>건수</strong></td><td style="text-align:left;">해당 인력에게 배정된 정산 대상 계약 건수</td></tr><tr><td style="text-align:left;"><strong>인센티브</strong></td><td style="text-align:left;">건당 수수료 정책에 의해 계산된 성과 수수료 합계</td></tr><tr><td style="text-align:left;"><strong>기본급 / 일비</strong></td><td style="text-align:left;">기본 지급액 또는 일비 보조금</td></tr><tr><td style="text-align:left;"><strong>공제 / 환수</strong></td><td style="text-align:left;">과거 해약 등으로 발생한 미정산 환수금 상계 차감액</td></tr><tr><td style="text-align:left;"><strong>총액 (세전)</strong></td><td style="text-align:left;">세전 지급 총액 (<code>인센티브 + 기본급 - 환수액</code>)</td></tr><tr><td style="text-align:left;"><strong>원천세 (3.3%)</strong></td><td style="text-align:left;">사업소득세(3%) + 지방소득세(0.3%) 합계 (10원 단위 절사)</td></tr><tr><td style="text-align:left;"><strong>실지급액 (세후)</strong></td><td style="text-align:left;">금융기관을 통해 실제 이체될 최종 지급 금액</td></tr><tr><td style="text-align:left;"><strong>상태</strong></td><td style="text-align:left;">지급 진행 상태 (<code>지급대기</code>, <code>지급승인</code>, <code>지급완료</code>, <code>지급보류</code>)</td></tr><tr><td style="text-align:left;"><strong>상세</strong></td><td style="text-align:left;"><code>[보기]</code> 버튼 클릭 시 계약 건별 산출 근거 모달 호출</td></tr></tbody></table><h3 id="_4-정산-회차-생성-모달-periodformmodal" tabindex="-1">4. 정산 회차 생성 모달 (PeriodFormModal) <a class="header-anchor" href="#_4-정산-회차-생성-모달-periodformmodal" aria-label="Permalink to &quot;4. 정산 회차 생성 모달 (PeriodFormModal)&quot;">​</a></h3><p>새로운 정산 주기를 시작하기 위한 기본 설정 팝업입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">입력 항목</th><th style="text-align:center;">필수 여부</th><th style="text-align:left;">설명 및 비고</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>정산 회차명</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">예: &quot;2026년 9월 1회차 수수료 정산&quot;</td></tr><tr><td style="text-align:left;"><strong>정산 대상 시작일</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">실적 집계 대상 시작일 (<code>DatePicker</code>)</td></tr><tr><td style="text-align:left;"><strong>정산 대상 종료일</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">실적 집계 대상 종료일 (<code>DatePicker</code>)</td></tr><tr><td style="text-align:left;"><strong>지급 예정일</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">금융 이체 예정 일자 (<code>DatePicker</code>)</td></tr><tr><td style="text-align:left;"><strong>정산 상태</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">기본값: &quot;정산 작성 중&quot;</td></tr></tbody></table><h3 id="_5-개인별-수수료-정산-상세-모달-payoutdetailmodal" tabindex="-1">5. 개인별 수수료 정산 상세 모달 (PayoutDetailModal) <a class="header-anchor" href="#_5-개인별-수수료-정산-상세-모달-payoutdetailmodal" aria-label="Permalink to &quot;5. 개인별 수수료 정산 상세 모달 (PayoutDetailModal)&quot;">​</a></h3><p>특정 영업 인력의 정산 산출 근거와 계좌 정보, 그리고 어떤 계약들로 인해 수수료가 발생했는지를 세부 증빙 형태로 보여줍니다.</p><ul><li><strong>기본 인적사항 및 계좌 정보</strong>: 성명, 직책, 소속 팀, 입금 은행명, 계좌번호, 예금주</li><li><strong>금액 산출 구성</strong>: 인센티브 합계, 기본급, 공제/환수액</li><li><strong>원천세 계산표</strong>: 세전총액, 사업소득세, 지방소득세, 원천징수 합계, 세후 실지급액</li><li><strong>정산 대상 계약 상세 목록</strong>: 계약 일련번호, 계약자명, 수당 구분(상담사/팀장/본부장), 건당 수수료 금액</li></ul>',22)])])}const x=e(r,[["render",d]]);export{f as __pageData,x as default};
